# Generated by build.py from recipe.yml for recipe ws-receive-a-large-file-in-frames. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir site'
cmd /c 'head -c 200000 /dev/urandom > site/big.bin'
cmd /c 'head -c 65536 /dev/urandom > site/at-limit.bin'
cmd /c 'head -c 65537 /dev/urandom > site/over-limit.bin'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'ws://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o got.bin ws://127.0.0.1:8080/big.bin && cmp got.bin site/big.bin && echo identical } finally { Stop-Process $server0 }
